<?php require_once 'bootstrap.php';$tok=(string)($_GET['token']??'');$st=db()->prepare('SELECT * FROM certificates WHERE verify_token=?');$st->execute([$tok]);$c=$st->fetch();if(!$c){http_response_code(404);exit('Attestato non trovato');}?><!doctype html><html lang="it"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title><?=h($c['title'])?></title><style>body{font-family:Arial,sans-serif;background:#f5f7fa;color:#071B33;margin:0;padding:30px}.cert{max-width:850px;margin:auto;background:white;border:10px solid #071B33;padding:50px;text-align:center}.green{color:#22C55E}.sic{font-family:monospace;color:#607284}@media print{@page{size:A4 landscape;margin:12mm}button{display:none}body{padding:0}.cert{box-shadow:none}}</style></head><body><div class="cert"><p class="green"><b>OLTRE · DEPENDEX</b></p><h1><?=h($c['title'])?></h1><p>Attestato digitale di traguardo</p><h2><?=h($c['certificate_type'])?></h2><p>Emesso il <?=h($c['issued_at'])?></p><p class="sic"><?=h($c['sic_id'])?></p><p class="sic">Verification token: <?=h($c['verify_token'])?></p><button onclick="print()">Stampa / PDF</button></div></body></html>